<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{getWeeklyReport}from'../services/weeklyService';import type{WeeklyReport}from'../types/weekly'
const data=ref<WeeklyReport|null>(null),loading=ref(true),error=ref('');const maxLoad=computed(()=>Math.max(1,...(data.value?.days.map(x=>x.totalLoad)??[])))
const weeklyQuery=computed(()=>{const x=data.value;if(!x)return{};const knee=x.days.filter(day=>day.kneeState==='attention').length,trend=x.work.comparison.hasComparison?` Cambio del promedio laboral diario frente a la semana previa: ${signed(x.work.comparison.actualMinutesPerDayChange)} minutos; cambio del tiempo adicional diario: ${signed(x.work.comparison.extraMinutesPerDayChange)} minutos.`:'',context=x.work.context.contextRecordedDays?` Contexto laboral detallado en ${x.work.context.contextRecordedDays} jornada(s): ${x.work.context.totalBreakMinutes} minutos de pausas informadas y ${x.work.context.unusualDays} día(s) con condiciones inusuales.`:'';return{source:'weekly',date:x.to,title:`Revisión semanal · ${date(x.from)} — ${date(x.to)}`,category:'Revisión semanal',observation:`Período: ${date(x.from)} a ${date(x.to)}. Cobertura: ${x.dataCoverage} de 7 días. Carga total: ${x.current.totalLoad} UA (${x.current.trainingLoad} de entrenamiento y ${x.current.externalLoad} de actividad cotidiana). Sesiones completadas: ${x.current.sessions}. Jornadas comparables: ${x.work.current.recordedDays}; diferencia laboral neta: ${x.work.current.differenceMinutes} minutos; tiempo adicional acumulado: ${x.work.current.extraMinutes} minutos.${trend}${context} Check-ins: ${x.current.checkIns}. Fatiga promedio: ${x.current.averageFatigue??'sin datos'}/10. Dolor promedio: ${x.current.averagePain??'sin datos'}/10. Días con señales funcionales de atención: ${knee}. Decisiones registradas: ${x.review.decisions}. Acciones abiertas: ${x.review.openLearningActions}. Seguimientos aplicados esta semana: ${x.review.appliedLearningActions}.`}})
const date=(v:string,weekday=false)=>new Date(`${v}T12:00:00`).toLocaleDateString('es-AR',weekday?{weekday:'short',day:'2-digit'}:{day:'2-digit',month:'short'})
const value=(v:number|null,suffix='')=>v===null?'—':`${v}${suffix}`
const hours=(minutes:number)=>Math.round(minutes/60*10)/10
const signed=(value:number|null)=>value===null?'sin datos':`${value>0?'+':''}${value}`
const nextWeekDate=computed(()=>{const value=data.value?.to;if(!value)return'';const next=new Date(`${value}T12:00:00`);next.setDate(next.getDate()+1);return next.toISOString().slice(0,10)})
const workPlanning=computed(()=>{const work=data.value?.work;if(!work||!work.current.recordedDays)return'Primero registrá jornadas desde el horario para construir una base comparable.';if(!work.comparison.hasComparison)return'Esta es la primera semana laboral comparable. Conservá el registro para poder contrastarla con la próxima.';const actual=work.comparison.actualMinutesPerDayChange??0,extra=work.comparison.extraMinutesPerDayChange??0;return`El promedio diario registrado fue ${Math.abs(actual)} min ${actual>0?'mayor':actual<0?'menor':'igual'} y el tiempo adicional promedio fue ${Math.abs(extra)} min ${extra>0?'mayor':extra<0?'menor':'igual'} que la semana previa.`})
onMounted(async()=>{try{data.value=await getWeeklyReport()}catch(e){error.value=e instanceof Error?e.message:'No se pudo abrir el resumen.'}finally{loading.value=false}})
</script>
<template><section class="page weekly-page" :class="{muted:loading}"><div class="page-heading"><div><span class="eyebrow">Lectura de siete días</span><h1>Resumen semanal</h1><p>Integra entrenamiento, actividad cotidiana, bienestar y función de rodilla sin predecir lesiones.</p></div><span v-if="data" class="data-depth">{{date(data.from)}} — {{date(data.to)}}</span></div><div v-if="error" class="notice error">{{error}}</div><template v-if="data"><div class="weekly-coverage"><span>Datos en {{data.dataCoverage}} de 7 días</span><i><b :style="{width:`${data.dataCoverage/7*100}%`}"></b></i><small>Los promedios se calculan solamente con registros disponibles.</small></div>
<article v-if="data.activeCycle" class="panel weekly-cycle"><div><span class="eyebrow">Ciclo activo</span><h2>{{data.activeCycle.name}}</h2><p>{{data.activeCycle.focus}} · hasta {{date(data.activeCycle.endDate)}}</p></div><div><strong>{{data.activeCycle.completedSessions}} / {{data.activeCycle.expectedSessions}}</strong><span>sesiones cumplidas hasta hoy</span><i><b :style="{width:`${Math.min(100,data.activeCycle.adherencePercent??0)}%`}"></b></i><small>{{data.activeCycle.adherencePercent??'—'}}% de cumplimiento</small></div></article><div class="weekly-kpis"><article><span>Carga total</span><strong>{{data.current.totalLoad}} UA</strong><small v-if="data.comparison.totalLoadPercent!==null">{{data.comparison.totalLoadPercent>0?'+':''}}{{data.comparison.totalLoadPercent}}% vs. semana previa</small><small v-else>Sin base anterior comparable</small></article><article><span>Entrenamiento</span><strong>{{data.current.trainingLoad}} UA</strong><small>{{data.current.sessions}} sesiones · {{data.current.trainingMinutes}} min</small></article><article><span>Actividad cotidiana</span><strong>{{data.current.externalLoad}} UA</strong><small>{{data.current.activityMinutes}} minutos registrados</small></article><article><span>Fatiga promedio</span><strong>{{value(data.current.averageFatigue,' / 10')}}</strong><small>{{data.comparison.fatigueChange===null?'Sin comparación':`${data.comparison.fatigueChange>0?'+':''}${data.comparison.fatigueChange} puntos`}}</small></article><article><span>Dolor promedio</span><strong>{{value(data.current.averagePain,' / 10')}}</strong><small>{{data.current.kneeChecks}} controles de rodilla</small></article></div>
<article class="panel weekly-work"><div><span class="eyebrow">Trabajo previsto y realizado</span><h2>Contexto laboral de la semana</h2><p v-if="data.work.current.recordedDays">Comparación disponible en {{data.work.current.recordedDays}} jornada{{data.work.current.recordedDays===1?'':'s'}} registrada{{data.work.current.recordedDays===1?'':'s'}}.</p><p v-else>Las próximas jornadas registradas desde el horario permitirán construir esta comparación.</p></div><div class="weekly-work-numbers"><article><span>Previsto</span><strong>{{hours(data.work.current.plannedMinutes)}} h</strong></article><article><span>Realizado</span><strong>{{hours(data.work.current.actualMinutes)}} h</strong></article><article :class="{attention:data.work.current.extraMinutes}"><span>Tiempo adicional</span><strong>{{data.work.current.extraMinutes}} min</strong><small>{{data.work.current.daysWithExtra}} día(s)</small></article><article><span>Diferencia neta</span><strong>{{data.work.current.differenceMinutes>0?'+':''}}{{data.work.current.differenceMinutes}} min</strong><small>Incluye días más cortos</small></article></div><div v-if="data.work.context.contextRecordedDays" class="weekly-work-details"><header><span><strong>{{data.work.context.contextRecordedDays}}</strong> jornadas detalladas</span><span><strong>{{data.work.context.totalBreakMinutes}}</strong> min de pausas informadas</span><span :class="{attention:data.work.context.unusualDays}"><strong>{{data.work.context.unusualDays}}</strong> días inusuales</span></header><div v-if="data.work.context.demands.length" class="weekly-work-demands"><small>Demandas registradas</small><span v-for="item in data.work.context.demands" :key="item">{{item}}</span></div><div v-if="data.work.context.unusualConditions.length" class="weekly-work-unusual"><small>Condiciones fuera de lo habitual</small><p v-for="item in data.work.context.unusualConditions" :key="`${item.date}-${item.text}`"><b>{{date(item.date,true)}}</b> · {{item.text}}</p></div></div><div class="weekly-work-planning"><div><span class="eyebrow">Lectura para planificar</span><strong>{{workPlanning}}</strong><small>Pregunta sugerida: ¿hay algo que quieras mantener o corregir explícitamente en la próxima semana?</small></div><RouterLink :to="{path:'/agenda',query:{date:nextWeekDate}}" class="secondary-button">Revisar próxima semana</RouterLink></div><footer>La comparación usa promedios por jornada para no confundir semanas con distinta cantidad de registros. Los minutos de pausa son un hecho informado, no una medición automática de recuperación. No se atribuyen cambios físicos al trabajo.</footer></article>
<div class="weekly-grid"><article class="panel weekly-chart"><div class="panel-heading"><div><span class="eyebrow">Distribución diaria</span><h2>Carga total por origen</h2></div><span class="evidence-chip">minutos × RPE</span></div><div class="weekly-bars"><div v-for="day in data.days" :key="day.date"><span>{{day.totalLoad||''}}</span><div class="weekly-stack"><i class="external" :style="{height:`${day.externalLoad/maxLoad*100}%`}"></i><i class="training" :style="{height:`${day.trainingLoad/maxLoad*100}%`}"></i></div><small>{{date(day.date,true)}}</small></div></div><div class="weekly-legend"><span><i class="training"></i> Entrenamiento</span><span><i class="external"></i> Actividad cotidiana</span></div></article><article class="panel weekly-signals"><div class="panel-heading"><div><span class="eyebrow">Lectura explicable</span><h2>Señales</h2></div></div><div class="signal-list"><div v-for="s in data.signals" :key="s.title" class="insight-signal" :class="s.kind"><span>{{s.kind==='attention'?'!':s.kind==='observe'?'↗':'i'}}</span><div><strong>{{s.title}}</strong><p>{{s.detail}}</p><small>{{s.basis}}</small></div></div></div></article></div>
<article class="panel weekly-reflection"><div><span class="eyebrow">Cierre guiado</span><h2>Convertir la semana en aprendizaje</h2><p>Atlas prepara sólo el resumen comprobable. Vos completás qué podría significar y qué querés hacer después.</p><small>Una semana aislada no demuestra causalidad ni reemplaza evaluación profesional.</small></div><div class="weekly-review-facts"><span><strong>{{data.review.decisions}}</strong> decisiones</span><span><strong>{{data.review.openLearningActions}}</strong> acciones abiertas</span><span :class="{attention:data.review.dueLearningActions}"><strong>{{data.review.dueLearningActions}}</strong> para revisar</span><span><strong>{{data.review.appliedLearningActions}}</strong> seguimientos</span></div><RouterLink v-if="data.review.hasReflection&&data.review.reflectionId" :to="{path:'/bitacora',query:{entry:data.review.reflectionId}}" class="secondary-button">Abrir reflexión de hoy</RouterLink><RouterLink v-else :to="{path:'/bitacora',query:weeklyQuery}" class="primary-button">Crear reflexión semanal</RouterLink></article>
<article class="panel weekly-table"><div class="panel-heading"><div><span class="eyebrow">Contexto</span><h2>Día por día</h2></div></div><div class="weekly-row header"><span>Día</span><span>Carga</span><span>Registros</span><span>Fatiga</span><span>Dolor</span><span>Rodilla</span></div><div v-for="day in data.days" :key="day.date" class="weekly-row"><strong>{{date(day.date,true)}}</strong><span>{{day.totalLoad}} UA<small>{{day.trainingLoad}} + {{day.externalLoad}}</small></span><span>{{day.sessions}} sesión · {{day.activities}} extra<small>{{day.hasCheckIn?'Check-in ✓':'Sin check-in'}}</small></span><span>{{value(day.fatigue,' / 10')}}</span><span>{{value(day.pain,' / 10')}}</span><em :class="day.kneeState">{{day.kneeState==='attention'?'Atención':day.kneeState==='observe'?'Observar':day.kneeState==='stable'?'Estable':'Sin control'}}</em></div></article></template></section></template>
